class _PulseState extends State<Pulse> with SingleTickerProviderStateMixin {
  // vsync: this -> createTicker(): one Ticker, driven by the frame clock
  late final AnimationController _pulse = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 900),
  )..repeat(reverse: true);

  @override
  void dispose() {
    _pulse.dispose(); // disposes the Ticker too
    super.dispose();
  }

  @override
  Widget build(BuildContext context) =>
      ScaleTransition(scale: _pulse, child: const Icon(Icons.favorite));
}

// ❌ A second controller on the Single mixin asserts:
