//     were created" — the mixin only ever hands out one.

// ✅ Two controllers -> the plural mixin, which keeps a Set of tickers
class _SheetState extends State<Sheet> with TickerProviderStateMixin {
  late final _slide = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 300));
  late final _fade = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 150));

  @override
  void dispose() {
    _slide.dispose();
    _fade.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => const SizedBox.shrink();
}

// What vsync buys you: TickerMode gates every ticker below it, so an
// off-screen subtree stops requesting frames instead of burning battery.
Widget onlyTickWhenVisible(bool visible, Widget child) =>
    TickerMode(enabled: visible, child: child);

late final AnimationController c = AnimationController(
  vsync: this,
  duration: const Duration(milliseconds: 400),
  reverseDuration: const Duration(milliseconds: 250), // separate way back
)..addStatusListener((s) => debugPrint('$s @ ${c.value.toStringAsFixed(2)}'));

// forward:  AnimationStatus.forward   -> AnimationStatus.completed  @ 1.00
// reverse:  AnimationStatus.reverse   -> AnimationStatus.dismissed  @ 0.00

c.forward();                 // 0.0 -> 1.0
c.forward(from: 0.25);       // snap to 0.25, then run up

// ❌ never reports completed: repeat only turns around, it never stops
c.repeat(reverse: true);
if (c.status == AnimationStatus.completed) {
  // dead code for a looping controller
}

// ✅ a loop you can end: stop it yourself, then settle to an end
void settle() {
  c.stop();                  // value frozen mid-flight, status unchanged
  c.animateTo(c.value > 0.5 ? 1.0 : 0.0); // now an end is actually reached
}

// stop() vs reset()
c.stop();                    // value 0.43, status still forward
debugPrint('${c.isAnimating}');  // false
c.reset();                   // value 0.0, status dismissed

// Jump without animating — listeners still fire, so the UI follows a drag
c.value = (c.value + delta / 200).clamp(0.0, 1.0);

class _FaderState extends State<Fader> with SingleTickerProviderStateMixin {
  // ✅ built once, for the life of the State
  late final AnimationController _c =
      AnimationController(vsync: this, duration: widget.duration);

  @override
  void didUpdateWidget(Fader old) {
    super.didUpdateWidget(old);
    // ✅ mutate in place — the animation keeps its value and keeps playing
    if (widget.duration != old.duration) _c.duration = widget.duration;
  }

  Future<void> _load() async {
    await context.read<Repo>().fetch();
    if (!mounted) return;            // the State may be gone by now
    _c.forward();                    // without the guard: used after dispose
  }

  @override
  void dispose() {
    _c.dispose();                    // stops and disposes the Ticker
    super.dispose();
  }

  @override
  Widget build(BuildContext context) =>
      FadeTransition(opacity: _c, child: widget.child);
}

