class _CardState extends State<Card> with SingleTickerProviderStateMixin {
  late final _c = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 350));

  // Types with arithmetic ride the base Tween
  late final Animation<Offset> _slide =
      Tween(begin: const Offset(0, 0.15), end: Offset.zero).animate(_c);

  // Color has no operator- : that is what ColorTween exists for.
  // Note the nullable value type.
  late final Animation<Color?> _tint =
      ColorTween(begin: Colors.grey.shade300, end: Colors.teal).animate(_c);

  // TextStyle interpolates through TextStyle.lerp
  late final Animation<TextStyle> _title = TextStyleTween(
    begin: const TextStyle(fontSize: 14, fontWeight: FontWeight.w400),
    end: const TextStyle(fontSize: 22, fontWeight: FontWeight.w700),
  ).animate(_c);

  // chain(): curve + tween composed once, still reusable
  late final Animation<double> _scale = _c.drive(
    Tween(begin: 0.9, end: 1.0).chain(CurveTween(curve: Curves.easeOutCubic)),
  );

  @override
  void dispose() { _c.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) => SlideTransition(
        position: _slide,
        child: ScaleTransition(
          scale: _scale,
          child: AnimatedBuilder(
            animation: _tint,
            builder: (_, __) => ColoredBox(
              color: _tint.value!,
              child: DefaultTextStyle(style: _title.value, child: widget.child),
            ),
          ),
        ),
      );
}

