// ✅ interruption is a real outcome, so handle it
Future<void> close() async {
  try {
    await _c.reverse().orCancel;
  } on TickerCanceled {
    return;                    // someone re-opened the sheet mid-flight
  }
  if (!context.mounted) return;
  Navigator.of(context).pop();
}

