  super.initState();
  _c.addStatusListener(_onStatus);
}

void _onStatus(AnimationStatus status) {
  if (status == AnimationStatus.dismissed) {
    if (!mounted) return;
    setState(() => _hidden = true);   // fires on every close, not just the first
  }
}

