class _RevealState extends State<Reveal> with SingleTickerProviderStateMixin {
  // One clock for the whole sequence: 300 + 300 + 300
  late final _c = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 900));

  // Slices are FRACTIONS of that duration, not durations of their own
  late final Animation<double> _cardFade = CurvedAnimation(
    parent: _c,
    curve: const Interval(0.0, 0.33, curve: Curves.easeOut),
  );

  late final Animation<Offset> _titleSlide =
      Tween(begin: const Offset(0, 0.25), end: Offset.zero).animate(
    CurvedAnimation(
      parent: _c,
      curve: const Interval(0.33, 0.66, curve: Curves.easeOutCubic),
    ),
  );

  late final Animation<double> _buttonPop = Tween(begin: 0.8, end: 1.0).animate(
    CurvedAnimation(
      parent: _c,
      // overlaps the slide slightly -> the two motions blend
      curve: const Interval(0.6, 1.0, curve: Curves.easeOutBack),
    ),
  );

  @override
  void initState() { super.initState(); _c.forward(); }

  @override
  void dispose() { _c.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) => FadeTransition(
        opacity: _cardFade,
        child: Column(children: [
          SlideTransition(position: _titleSlide, child: const Title()),
          ScaleTransition(scale: _buttonPop, child: const CtaButton()),
        ]),
      );
  // _c.reverse() unwinds all three in the right order, from wherever it is.
}

