// ❌ nothing animates: both children are Text with no key,
//    so Widget.canUpdate says "same widget, new data"
AnimatedSwitcher(
  duration: const Duration(milliseconds: 250),
  child: Text(_label),
);

// ✅ a distinct key per value makes the swap visible
AnimatedSwitcher(
  duration: const Duration(milliseconds: 250),
  child: Text(_label, key: ValueKey(_label)),
);

// Full control: symmetric transition + top-aligned layout
AnimatedSwitcher(
  duration: const Duration(milliseconds: 250),
  reverseDuration: const Duration(milliseconds: 150), // faster exit
  switchInCurve: Curves.easeOut,
  switchOutCurve: Curves.easeIn,

  // runs for the incoming child AND for the outgoing one in reverse
  transitionBuilder: (child, animation) => FadeTransition(
    opacity: animation,
    child: SlideTransition(
      position: Tween(begin: const Offset(0, 0.08), end: Offset.zero)
          .animate(animation),
      child: child,
    ),
  ),

  // default stacks centred and sizes to the tallest child; pin to the top
  layoutBuilder: (currentChild, previousChildren) => Stack(
    alignment: Alignment.topCenter,
    children: [...previousChildren, if (currentChild != null) currentChild],
  ),

  child: _loading
      ? const CircularProgressIndicator(key: ValueKey('spinner'))
      : Text(_result, key: ValueKey(_result)),
);

// Animate the box as well as its contents
