class _InboxState extends State<Inbox> {
  final _listKey = GlobalKey<AnimatedListState>();
  final List<Mail> _mails = List<Mail>.of(seedMails);

  Widget _row(Mail mail, Animation<double> animation) => SizeTransition(
        sizeFactor: animation.drive(CurveTween(curve: Curves.easeOut)),
        child: FadeTransition(
          opacity: animation,
          child: ListTile(title: Text(mail.subject)),
        ),
      );

  void _archive(int index) {
    // Capture BEFORE mutating: the builder runs once the item is gone
    final removed = _mails[index];
    _mails.removeAt(index);
    _listKey.currentState!.removeItem(
      index,                                            // pre-removal index
      (context, animation) => _row(removed, animation), // animation: 1 -> 0
      duration: const Duration(milliseconds: 250),
    );
  }

  // Several at once: highest index first, or the rest shift under you
  void _archiveAll(List<int> indexes) {
    for (final i in (indexes.toList()..sort()).reversed) {
      _archive(i);
    }
  }

  @override
  Widget build(BuildContext context) => AnimatedList(
        key: _listKey,
        initialItemCount: _mails.length,   // the list counts, not your data
        itemBuilder: (context, index, animation) =>
            _row(_mails[index], animation),
      );
}

