class _LikeButtonState extends State<LikeButton> {
  SMIBool? _liked;

  @override
  Widget build(BuildContext context) => GestureDetector(
        // No seeking: set an input, the machine picks the transition
        onTap: () => _liked?.value = !_liked!.value,
        child: RiveAnimation.asset(
          'assets/like.riv',
          onInit: (artboard) {
            final sm = StateMachineController.fromArtboard(artboard, 'Like')!;
            artboard.addController(sm);
            _liked = sm.findInput<bool>('liked') as SMIBool?;
          },
        ),
      );
}

