class _SheetState extends State<Sheet> with SingleTickerProviderStateMixin {
  static const double _extent = 320;   // sheet height in logical pixels

  late final _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 300),
  );   // 0 = hidden, 1 = open

  void _onDragUpdate(DragUpdateDetails d) {
    // Writing value stops any running animation and clamps to 0..1
    _c.value -= d.primaryDelta! / _extent;
  }

  void _onDragEnd(DragEndDetails d) {
    // pixels/second -> fractions of the sheet per second
    final velocity = -d.velocity.pixelsPerSecond.dy / _extent;
    if (velocity.abs() >= 1.0) {
      _c.fling(velocity: velocity);            // keep the thumb's speed
    } else {
      _c.fling(velocity: _c.value < 0.5 ? -1 : 1);   // settle to the near end
    }
  }

  @override
  Widget build(BuildContext context) => GestureDetector(
        onVerticalDragUpdate: _onDragUpdate,
        onVerticalDragEnd: _onDragEnd,
        child: SlideTransition(
          // repaint only: no rebuild while the finger moves
          position: _c.drive(
            Tween(begin: const Offset(0, 1), end: Offset.zero),
          ),
          child: const SheetBody(),
        ),
      );

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }
}

