class _CardState extends State<DraggableCard>
    with SingleTickerProviderStateMixin {
  // unbounded: an underdamped spring overshoots past the target and
  // a clamped controller would eat the overshoot
  late final _c = AnimationController.unbounded(vsync: this);

  static final _spring = SpringDescription.withDampingRatio(
    mass: 1,
    stiffness: 500,
    ratio: 0.6,   // < 1 → passes the target, comes back, settles
  );

  void _onDragUpdate(DragUpdateDetails d) =>
      _c.value += d.primaryDelta! / context.size!.width;

  void _onDragEnd(DragEndDetails d) {
    _c.animateWith(SpringSimulation(
      _spring,
      _c.value,                                          // where it is
      0,                                                 // where it belongs
      d.velocity.pixelsPerSecond.dx / context.size!.width, // how fast it goes
    ));
  }

  @override
  Widget build(BuildContext context) => GestureDetector(
        onHorizontalDragUpdate: _onDragUpdate,
        onHorizontalDragEnd: _onDragEnd,
        child: SlideTransition(
          position: _c.drive(
            Tween(begin: Offset.zero, end: const Offset(1, 0)),
          ),
          child: const CardBody(),
        ),
      );

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }
}

