// 2 — only positions change: lay out once, place with matrices, never relayout
class FanDelegate extends FlowDelegate {
  FanDelegate(this.animation) : super(repaint: animation);

  final Animation<double> animation;

  @override
  void paintChildren(FlowPaintingContext context) {
    final radius = 72.0 * animation.value;
    for (var i = 0; i < context.childCount; i++) {
      final angle = i * 0.4;
      context.paintChild(
        i,
        transform: Matrix4.translationValues(
          radius * cos(angle),
          -radius * sin(angle),
          0,
        ),
        opacity: animation.value,
      );
    }
  }

  // `repaint:` already repaints every tick; this only covers a new delegate
  @override
  bool shouldRepaint(FanDelegate old) => animation != old.animation;
}

Flow(delegate: FanDelegate(_controller), children: actionButtons);

