class AnimatedRing extends ImplicitlyAnimatedWidget {
  const AnimatedRing({
    super.key,
    required this.color,
    required this.thickness,
    required super.duration,
    super.curve,
    super.onEnd,
  });

  final Color color;
  final double thickness;

  @override
  AnimatedWidgetBaseState<AnimatedRing> createState() => _AnimatedRingState();
}

class _AnimatedRingState extends AnimatedWidgetBaseState<AnimatedRing> {
  ColorTween? _color;          // Color has no + - *, so not Tween<Color>
  Tween<double>? _thickness;

  @override
  void forEachTween(TweenVisitor<dynamic> visitor) {
    // Every property, every call — a skipped one silently freezes
    _color = visitor(
      _color,
      widget.color,
      (v) => ColorTween(begin: v as Color),   // only used the first time
    ) as ColorTween?;

    _thickness = visitor(
      _thickness,
      widget.thickness,
      (v) => Tween<double>(begin: v as double),
    ) as Tween<double>?;
  }

  @override
  Widget build(BuildContext context) {
    // `animation` is the curved animation the base class drives for us
    return CustomPaint(
      painter: RingPainter(
        color: _color!.evaluate(animation)!,
        thickness: _thickness!.evaluate(animation),
      ),
    );
  }
}

