class PageHeader extends StatelessWidget {
  const PageHeader({super.key, required this.title});

  final String title;

  @override
  Widget build(BuildContext context) {
    // The same animation the route's transitionsBuilder is driven by.
    // Null when there is no route above us (a bare pumpWidget in a test).
    final route = ModalRoute.of(context);
    final entering = route?.animation ?? kAlwaysCompleteAnimation;
    final covered = route?.secondaryAnimation ?? kAlwaysDismissedAnimation;

    return SlideTransition(
      // drive + chain allocate no listeners, so there is nothing to dispose
      position: entering.drive(
        Tween(begin: const Offset(0, 0.15), end: Offset.zero)
            .chain(CurveTween(curve: Curves.easeOutCubic)),
      ),
      child: FadeTransition(
        // fade out while the NEXT route covers this page
        opacity: covered.drive(Tween(begin: 1.0, end: 0.0)),
        child: Text(title, style: Theme.of(context).textTheme.headlineSmall),
      ),
    );
  }
}

